INSERT INTO `t_ksxx` VALUES ('21430106224966', 'A06351504', '谭*', '2', NULL, '13', '01', '43', '1', '5', '0', '010610', '****中学', '01', '1', NULL, '010610', '0106', '1', '440102********2329', NULL, NULL, NULL, '长沙市********', '410000', '1520080****', '1520080****', '刘*', '钢琴', 'nan', '你文静而有内涵，积极向上，乐观开朗，热爱集体，学习认真，善于思考，对老师有礼貌，能够团结同学，是一个各方面表现不错的学生。希望你百尺竿头，更进一步，取得更好的成绩。思想品德考核意见为“优秀”。', '01', '4****4', NULL, '04*05*09', '000', '2', '9', '0', '06', 45, 574, 574, 574, 0, '40', '2021-07-11', '10', NULL, 1, 1, 1, 1, 38, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `t_ksxx` VALUES ('21430201228266', 'B01352407', '郑*萱', '2', NULL, '03', '01', '43', '1', '5', '0', '020120', '****中学', '01', '1', NULL, '020120', '0201', '1', '430211********4029', NULL, NULL, NULL, '湖南省********', '412000', '1397538****', '1397538****', '郑*萱', '舞蹈古筝播音主持声乐', '2020.8.1综合素质优秀分子2019.12.29优秀礼仪20', '你聪明、自信、有责任心。在担任班干部的工作上，有组织能力，在同学中有一定的威信，能带领同学积极完成老师交给的各项任务。在学习上方法得当，成绩优秀。希望进一步发挥主观能动性。坚信自己的汗水，能使贫脊的土地萌出希望之果。', '01', '4****1', NULL, '04*05*09', '000', '2', '9', '0', '06', 45, 548, 548, 548, 0, '39', '2021-07-11', '10', NULL, 1, 1, 1, 4, 38, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `t_ksxx` VALUES ('21430321241440', 'C21341108', '胡*怡', '2', NULL, '03', '01', '43', '1', '5', '0', '032101', '****中学', '01', '1', NULL, '032101', '0321', '1', '430321********0183', NULL, NULL, NULL, '长沙市********', '123456', '1301616****', '1301616****', '胡*怡', '画画播音主持表演', '学校三好学生，学习积极分子', '该生热爱祖国，热爱集体，纪律观念强，为人正直，有上进心，尊敬师长，团结同学，有较好的人际关系，能够积极参加校内外各项有益的活动，工作认真负责，社会实践能力强。学习态度端正，学习热情高，成绩优异。身体素质好，播音与主持特长突出。是个德智体全面发展的好学生。', '02', '4****1', NULL, '04*06*09', '000', '2', '9', '0', '06', 45, 506, 506, 506, 0, '39', '2021-07-11', '10', NULL, 1, 1, 1, 5, 38, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `t_ksxx` VALUES ('21430624250394', 'F24320723', '常*月', '2', NULL, '03', '01', '43', '1', '5', '0', '062401', '****中学', '01', '1', NULL, '062401', '0624', '1', '430681********6786', NULL, 1, NULL, '湖南省********', '414400', '1511505****', '1511505****', '常*月', '钢琴，篮球，羽毛球', '2020湖南省潇湘家书荣获一等奖2017汨罗市初中生篮球赛女子组', '常*月同学在校期间尊敬师长，团结同学，热爱集体，热爱劳动，乐于助人，思维灵活，上进心强，有积极的学习态度，创新精神强，专业素养高，能够积极的参加校内外各项活动，是一名品学兼优的好学生！', '01', '4****1', NULL, '04*06*07', '000', '2', '9', '0', '06', 45, 561, 561, 561, 0, '40', '2021-07-11', '10', NULL, 1, 1, 1, 2, 38, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `t_ksxx` VALUES ('21430701214032', 'J01362627', '王*杰', '2', NULL, '03', '01', '43', '1', '5', '0', '070109', '****中学', '01', '1', NULL, '070109', '0701', '1', '430702********3526', NULL, NULL, NULL, '湖南省********', '415000', '1734741****', '1734741****', '王*杰', '舞蹈音乐绘画摄影葫芦丝', '小学：优秀少先队员初中：三好学生、五星学生高中：三好学生、优秀班', '你是一个上进心强，自尊心也很强，聪明而且心地善良的女孩。在学校，能尊敬老师，团结同学，拥有良好的纪律意识。上课时用心听讲的神情，让人感到你的专注认真。对于不明白的问题你能虚心请教他人，元旦汇演中你优美播报的嗓音，为班中添了不少荣誉。但有时在你遇到挫折时候', '01', '4****2', NULL, '04*05*06', '000', '2', '9', '0', '06', 45, 558, 558, 558, 0, '40', '2021-07-11', '10', NULL, 1, 1, 1, 3, 38, NULL, NULL, NULL, NULL, NULL, NULL);
